}

export function chunked(value, size) {
  const result = [];
  for (let index = 0; index < value.length; index += size) {
    result.push(value.slice(index, index + size));
  }
  return result;
}

export function partition(value, predicate) {
  const truthy = [];
  const falsy = [];

  for (const item of value) {
    if (predicate(item)) {
      truthy.push(item);
    } else {
      falsy.push(item);
    }
  }

  return new PyTuple([truthy, falsy]);
}

export function bucketize(value, keyFunction) {
  const result = new PyDict();
  const buckets = new Map();

  for (const item of value) {
    const key = keyFunction(item);
    const keyId = pyKeyId(key);
    if (!buckets.has(keyId)) {
      const bucket = [item];
      buckets.set(keyId, bucket);
      result.set(key, bucket);
      continue;
    }
    buckets.get(keyId).push(item);
  }

  return result;
}

function flattenInto(value, output) {
  const flattenable = flattenableItems(value);
  if (flattenable === null) {
    output.push(value);
    return;
  }

  for (const item of flattenable) {
    flattenInto(item, output);
  }
}

