export function parseCliArguments(argv, scriptPath) {
  const programName = basename(scriptPath || 'test19.mjs');
  const helpText = renderHelp(programName);

  if (argv.includes('-h') || argv.includes('--help')) {
    return {
      status: 'help',
      code: 0,
      stdout: helpText,
    };
  }

  let aValue;
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];

    if (argument === '--a') {
      const next = argv[index + 1];
      if (next === undefined || looksLikeOption(next)) {
        return argparseError(programName, 'argument --a: expected one argument');
      }
      aValue = next;
      index += 1;
      continue;
    }

    if (argument.startsWith('--a=')) {
      aValue = argument.slice(4);
      continue;
    }

    unknown.push(argument);
  }

  if (aValue === undefined) {
    return argparseError(programName, 'the following arguments are required: --a');
  }

  if (unknown.length > 0) {
    return argparseError(programName, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  return {
    status: 'ok',
    value: {
      a: aValue,
    },
  };
}

function argparseError(programName, message) {
  return {
    status: 'error',
    code: 2,
    stderr: `usage: ${programName} [-h] --a A\n${programName}: error: ${message}\n`,
  };
}

function renderHelp(programName) {
  return `usage: ${programName} [-h] --a A\n\noptions:\n  -h, --help  show this help message and exit\n  --a A       Nested dictionary structure\n`;
}

function basename(path) {
  const parts = path.split(/[\\/]/);
  return parts[parts.length - 1] || path;
}

function looksLikeOption(argument) {
  if (!argument.startsWith('-')) {
    return false;
  }
  return !/^-(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(argument);
}

